func main() {
	in := bufio.NewReader(os.Stdin)
	var n, t int
	if _, err := fmt.Fscan(in, &n, &t); err != nil {
		return
	}

	// dp[pos][prev][curr][peaks][valleys] = count
	// pos: current position index (1-based), we have fixed y[pos-1]=prev, y[pos]=curr
	// next y is at pos+1
	dp := make([][][][][]int64, n+1)
	for pos := 2; pos <= n-1; pos++ {
		dp[pos] = make([][][][]int64, 5)
		for prev := 1; prev <= 4; prev++ {
			dp[pos][prev] = make([][][]int64, 5)
			for curr := 1; curr <= 4; curr++ {
				dp[pos][prev][curr] = make([][]int64, t+1)
				for p := 0; p <= t; p++ {
					dp[pos][prev][curr][p] = make([]int64, t)
				}
			}
		}
	}

	// initialize for position 2: we have y1, y2
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			dp[2][y1][y2][0][0]++
		}
	}

	for pos := 2; pos <= n-1; pos++ {
		for prev := 1; prev <= 4; prev++ {
			for curr := 1; curr <= 4; curr++ {
				if prev == 0 || curr == 0 {
					continue
				}
				for peaks := 0; peaks <= t; peaks++ {
					for valleys := 0; valleys < t; valleys++ {
						val := dp[pos][prev][curr][peaks][valleys]
						if val == 0 {
							continue
						}
						for next := 1; next <= 4; next++ {
							if next == curr {
								continue
							}
							np, nv := peaks, valleys
							if prev < curr && curr > next {
								np++
							} else if prev > curr && curr < next {
								nv++
							}
							if np > t || nv >= t {
								continue
							}
							if pos+1 <= n-1 {
								dp[pos+1][curr][next][np][nv] += val
							}
						}
					}
				}
			}
		}
	}

	var ans int64
	if n == 2 {
		// Not possible because n >= 3 by constraints, but keep for completeness
		fmt.Println(0)
		return
	}

	// finalize at position n: we have last triple (y_{n-2}, y_{n-1}, y_n)
	pos := n - 1
	for prev := 1; prev <= 4; prev++ {
		for curr := 1; curr <= 4; curr++ {
			for peaks := 0; peaks <= t; peaks++ {
				for valleys := 0; valleys < t; valleys++ {
					val := dp[pos][prev][curr][peaks][valleys]
					if val == 0 {
						continue
					}
					for next := 1; next <= 4; next++ {
						if next == curr {
							continue
						}
						np, nv := peaks, valleys
						if prev < curr && curr > next {
							np++
						} else if prev > curr && curr < next {
							nv++
						}
						if np == t && nv == t-1 {
							ans += val
						}
					}
				}
			}
		}
	}

	fmt.Println(ans)
}
