	// Direction is undefined yet; we will set it at pos=2
	for y := 1; y <= 4; y++ {
		// store with both directions as possible starting states
		// but direction will only be meaningful from pos=2
		dp[1][y][0][0][0] = 1
		dp[1][y][1][0][0] = 1
	}

