								// but we don't store it; instead we infer by direction change:
								// if previous direction was increasing and now decreasing -> peak
								// if previous direction was decreasing and now increasing -> valley
								if dir == 1 && nd == 0 {
									np++
								} else if dir == 0 && nd == 1 {
									nv++
								}
								if np > t || nv >= t {
									continue
								}
							}
							dp[pos][ny][nd][np][nv] += cur
						}
					}
				}
			}
		}
	}

	var ans int64
	for last := 1; last <= 4; last++ {
		for dir := 0; dir < 2; dir++ {
			ans += dp[n][last][dir][t][t-1]
		}
