	var n, t int
	if _, err := fmt.Fscan(in, &n, &t); err != nil {
		return
	}

	// dp[pos][last][trend][peaks][valleys]
	// pos: current position (1..n)
	// last: last y value (1..4)
	// trend: 0 = flat (only at pos=1), 1 = up, 2 = down
	// peaks: number of peaks so far
	// valleys: number of valleys so far
	dp := make([][][][][]int64, n+1)
	for pos := 0; pos <= n; pos++ {
		dp[pos] = make([][][][]int64, 5)
		for last := 0; last <= 4; last++ {
			dp[pos][last] = make([][][]int64, 3)
			for tr := 0; tr < 3; tr++ {
				dp[pos][last][tr] = make([][]int64, t+1)
				for p := 0; p <= t; p++ {
					dp[pos][last][tr][p] = make([]int64, t) // valleys up to t-1
				}
			}
		}
	}

	// Initialize for position 1: any y in 1..4, trend=0, peaks=0, valleys=0
	for y := 1; y <= 4; y++ {
		dp[1][y][0][0][0] = 1
	}

	for pos := 1; pos < n; pos++ {
		for last := 1; last <= 4; last++ {
			for tr := 0; tr < 3; tr++ {
				for peaks := 0; peaks <= t; peaks++ {
					for valleys := 0; valleys < t; valleys++ {
						cur := dp[pos][last][tr][peaks][valleys]
						if cur == 0 {
							continue
						}
						// choose next y (must be != last)
						for next := 1; next <= 4; next++ {
							if next == last {
								continue
							}
							var ntr int
							npeaks, nvalleys := peaks, valleys

							if tr == 0 { // first step defines trend
								if next > last {
									ntr = 1
								} else {
									ntr = 2
								}
							} else if tr == 1 { // currently going up
								if next > last {
									ntr = 1
								} else { // turning down -> peak at pos
									ntr = 2
									npeaks++
								}
							} else { // tr == 2, currently going down
								if next < last {
									ntr = 2
								} else { // turning up -> valley at pos
									ntr = 1
									nvalleys++
								}
							}

							if npeaks > t || nvalleys >= t {
								continue
							}
							dp[pos+1][next][ntr][npeaks][nvalleys] += cur
						}
					}
				}
			}
		}
	}

	var ans int64
	for last := 1; last <= 4; last++ {
		for tr := 0; tr < 3; tr++ {
			ans += dp[n][last][tr][t][t-1]
		}
	}

	fmt.Println(ans)
}
